      color: '#6b5a48', ink: '#5a4a3a', tints: ['#f1ece5', '#e4dbcf'],
      kings: [
        { n: 1, name: '무단 통치', gen: false, s: 1910, e: 1919, keys: [{ name: '헌병 경찰', x: '헌병이 일반 경찰 업무까지 겸임했고, 순사와 헌병 보조원이 전국에 배치되어 치안을 담당했습니다.|혼동 주의: 헌병 경찰제 — 무단 통치, 1910년대 (보통 경찰제는 문화 통치 ✗)' }, { name: '토지 조사 사업', x: '임시 토지 조사국 설치(1910)와 토지 조사령(1912)으로 토지 소유자가 기한 안에 직접 신고하게 했습니다. 신고하지 못한 토지는 총독부 소유가 되었고 농민의 관습적 경작권(도지권)이 부정되어, 많은 자작농이 소작농으로 전락하거나 만주·연해주로 이주했습니다.|순서: 토지 조사 사업(1910년대) → 산미 증식 계획(1920년대) → 남면북양·농촌 진흥(1930년대) → 공출제·강제 동원(1940년대)' }, { name: '조선 태형령', x: '1912년 한국인에게만 태형(곤장형)을 적용한 민족 차별적 악법입니다. 3·1 운동 이후인 1920년에야 폐지되었습니다.' }, { name: '회사령', x: '1910년 공포되어 회사를 세울 때 총독의 허가를 받도록 해 한국인의 기업 활동을 억제했습니다.|순서: 회사령(1910, 허가제) → 회사령 폐지(1920, 신고제)' }, { name: '범죄 즉결례', x: '재판 없이 즉결 처분이 가능하도록 한 법입니다.' }, { name: '제1차 조선 교육령', x: '1911년 보통학교 수업 연한을 4년으로 줄여 우민화 교육을 실시했습니다.|순서: 1차(1911) → 2차(1922) → 3차(1938) → 4차(1943) 조선 교육령' }] },
        { n: 2, name: '문화 통치', gen: false, s: 1919, e: 1931, keys: [{ name: '산미 증식 계획', x: '1920~1934년 쌀 생산량을 늘렸으나 증산된 쌀의 대부분이 일본으로 반출되었습니다.|순서: 토지 조사 사업(1910년대) → 산미 증식 계획(1920년대) → 남면북양·농촌 진흥(1930년대) → 공출제·강제 동원(1940년대)' }, { name: '보통 경찰', x: '3·1 운동 뒤 헌병 경찰제를 보통 경찰제로 바꿨으나 경찰 수와 장비는 오히려 늘었습니다.|혼동 주의: 보통 경찰제 — 문화 통치, 1920년대 (헌병 경찰제는 무단 통치 ✗)' }, { name: '경성 제국 대학', x: '제2차 조선 교육령(1922)으로 대학 설립이 가능해진 것을 근거로 1924년 설립되었습니다.|관련: 이상재·이승훈 등의 민립 대학 설립 운동(1922)은 일제가 경성 제국 대학을 세우고 모금도 부진해 실현되지 못했습니다.' }, { name: '치안 유지법', x: '1925년 제정되었습니다.|관련: 1942년 일제가 이 법을 적용해 조선어학회 사건을 일으켰습니다.' }, { name: '회사령 철폐', x: '1920년 허가제에서 신고제로 바뀌어 일본 기업의 조선 진출이 쉬워졌습니다.|순서: 회사령(1910, 허가제) → 회사령 폐지(1920, 신고제)' }, { name: '관세 철폐', x: '1920년 회사령과 함께 조선 관세령도 폐지되어 일본 상품이 무관세로 대량 들어와 조선인 상공업이 큰 타격을 받았습니다.|관련: 이에 맞서 물산 장려 운동(1920)이 시작되었습니다.' }] },
        { n: 3, name: '민족 말살 통치', gen: false, s: 1931, e: 1945, keys: [{ name: '국가 총동원법', x: '1938년 인적·물적 자원을 전쟁에 강제로 동원할 수 있는 법적 근거를 마련했습니다.|순서: 일장기 말소 사건(1936) → 중일 전쟁·황국신민 서사(1937) → 국가 총동원법·제3차 교육령(1938) → 국민 징용령(1939) → 창씨개명·동아·조선일보 폐간(1940) → 국민학교령(1941) → 조선어학회 사건(1942) → 학도 지원병(1943) → 징병제(1944)' }, { name: '징용·징병', x: '인력 동원은 시간이 갈수록 강제성이 강해졌습니다. 국민 징용령(1939)으로 탄광·군수 공장에 노동자를 동원했고, 징병제(1944)로 "지원"이 아닌 강제 입영이 전면 실시되었습니다.|순서: 지원병제(1938) → 국민 징용령(1939) → 학도 지원병제(1943) → 징병제·여자 정신 근로령(1944)' }, { name: '창씨개명', x: '1940년 한국식 이름을 버리고 일본식 성과 이름을 쓰도록 강요했습니다.|관련: 제3차 조선 교육령(1938)·지원병제와 함께 황민화 정책의 핵심 축이었습니다.|순서: 일장기 말소 사건(1936) → 중일 전쟁·황국신민 서사(1937) → 국가 총동원법·제3차 교육령(1938) → 국민 징용령(1939) → 창씨개명·동아·조선일보 폐간(1940) → 국민학교령(1941) → 조선어학회 사건(1942) → 학도 지원병(1943) → 징병제(1944)' }, { name: '황국 신민 서사', x: '"나는 대일본 제국의 신민이다"로 시작하는 맹세문을 매일 외우게 했습니다. 1937년 미나미 지로 총독이 만들어 암송을 강요했습니다.' }, { name: '미곡 공출·배급', x: '배급제와 식량 공출을 실시하고, 금속류 회수령으로 놋그릇·종·숟가락까지 공출을 강행해 조선인의 일상을 극도로 통제했습니다.|순서: 토지 조사 사업(1910년대) → 산미 증식 계획(1920년대) → 남면북양·농촌 진흥(1930년대) → 공출제·강제 동원(1940년대)' }, { name: '신사 참배 강요', x: '일본 신도의 신사에 참배하도록 강제했고, 일본 천황이 사는 궁성 쪽으로 절하는 궁성 요배도 강요했습니다.' }, { name: '농촌 진흥 운동', x: '1932~1940년 "자력갱생·근검절약"을 표방했으나 실질적으로는 농촌 통제와 전시 동원 체제 정비가 목적이었고, 농촌 진흥 위원회가 주관했습니다.|순서: 토지 조사 사업(1910년대) → 산미 증식 계획(1920년대) → 남면북양·농촌 진흥(1930년대) → 공출제·강제 동원(1940년대)' }, { name: '국민학교', x: '1941년 국민학교령으로 소학교를 국민학교로 바꾸고 조선어 사용을 전면 금지했습니다.|관련: 제3차 조선 교육령(1938)은 조선어를 선택 과목으로 격하했습니다.|순서: 1차(1911) → 2차(1922) → 3차(1938) → 4차(1943) 조선 교육령' }, { name: '남면북양', x: '1929년 대공황 이후 한반도 남부에는 면화 재배를, 북부에는 면양을 장려해 일본 기업에 값싼 공업 원료를 확보했습니다.|순서: 토지 조사 사업(1910년대) → 산미 증식 계획(1920년대) → 남면북양·농촌 진흥(1930년대) → 공출제·강제 동원(1940년대)' }, { name: '병참 기지화', x: '만주사변(1931)과 중일 전쟁(1937)을 거치며 한반도 북부에 군수 공장을 세웠습니다.|순서: 토지 조사 사업(1910년대) → 산미 증식 계획(1920년대) → 남면북양·농촌 진흥(1930년대) → 공출제·강제 동원(1940년대)' }] },
      ],
